insert into public.dosage_reference (drug_name_ar, drug_name_en, age_group_ar, age_group_en, min_weight_kg, dose_text, weight_based, per_kg_low, per_kg_high, max_single_mg, max_daily, frequency_ar, frequency_en, warnings_ar, warnings_en, requires_rx, review_note) values ('سيميثيكون نقط (Simethicone) - مغص الرضع', 'Simethicone Drops - Infant Colic', 'رضع', 'Infants', 0, '0.3 مل (20 ملغم) لكل جرعة', false, null, null, 0, null, 'بعد كل رضعة عند الحاجة، حتى 4 مرات يومياً', 'After each feed as needed, up to 4 times daily', 'أدلة الفعالية محدودة علمياً، آمن نسبياً لكن ليس علاجاً مؤكداً لمغص الرضع', 'Limited scientific evidence of efficacy, relatively safe but not a proven treatment for infant colic', false, 'Imported from prototype; awaiting pharmacist review.');
insert into public.dosage_reference (drug_name_ar, drug_name_en, age_group_ar, age_group_en, min_weight_kg, dose_text, weight_based, per_kg_low, per_kg_high, max_single_mg, max_daily, frequency_ar, frequency_en, warnings_ar, warnings_en, requires_rx, review_note) values ('أونداسيترون (Ondansetron) - أطفال', 'Ondansetron - Children', 'أطفال فوق 6 أشهر (حسب تقييم الطبيب)', 'Children over 6 months (per doctor assessment)', 8, '0.15 ملغم/كغم/جرعة', false, null, null, 8, null, 'جرعة واحدة غالباً، لا تكرر إلا بإشراف طبي', 'Usually single dose, do not repeat without medical supervision', 'يوصف من طبيب فقط لحالات القيء المستمر (مثل التهاب المعدة والأمعاء)، حذر مع أمراض القلب النادرة (إطالة QT)', 'Prescribed by doctor only for persistent vomiting (e.g. gastroenteritis), caution with rare heart conditions (QT prolongation)', true, 'DATA ISSUE: 0.15 mg/kg dose stored as fixed (not weight-based). Confirm before approval.');
insert into public.dosage_reference (drug_name_ar, drug_name_en, age_group_ar, age_group_en, min_weight_kg, dose_text, weight_based, per_kg_low, per_kg_high, max_single_mg, max_daily, frequency_ar, frequency_en, warnings_ar, warnings_en, requires_rx, review_note) values ('أونداسيترون (Ondansetron) - بالغين', 'Ondansetron - Adults', 'بالغين', 'Adults', 40, '4-8 ملغم/جرعة ثابتة', false, null, null, 8, '24', 'كل 8 ساعات حسب وصف الطبيب', 'Every 8 hours as prescribed', 'يتطلب تقييم طبي، حذر مع أمراض القلب', 'Requires medical assessment, caution with heart disease', true, 'Imported from prototype; awaiting pharmacist review.');
insert into public.dosage_reference (drug_name_ar, drug_name_en, age_group_ar, age_group_en, min_weight_kg, dose_text, weight_based, per_kg_low, per_kg_high, max_single_mg, max_daily, frequency_ar, frequency_en, warnings_ar, warnings_en, requires_rx, review_note) values ('ميتوكلوبراميد (Metoclopramide)', 'Metoclopramide', 'أطفال وبالغين (بحذر شديد عند الأطفال)', 'Children and adults (extreme caution in children)', 0, '0.1-0.15 ملغم/كغم/جرعة', true, 0.1, 0.15, 10, '30', 'حسب وصف الطبيب فقط', 'As prescribed by doctor only', 'خطر آثار جانبية خارج هرمية (حركات لا إرادية) خصوصاً عند الأطفال، لا يُستخدم إلا بإشراف طبيب مباشر', 'Risk of extrapyramidal side effects (involuntary movements) especially in children, only used under direct doctor supervision', true, 'Imported from prototype; awaiting pharmacist review.');
insert into public.dosage_reference (drug_name_ar, drug_name_en, age_group_ar, age_group_en, min_weight_kg, dose_text, weight_based, per_kg_low, per_kg_high, max_single_mg, max_daily, frequency_ar, frequency_en, warnings_ar, warnings_en, requires_rx, review_note) values ('ديمينهيدرينات (Dimenhydrinate) - دوار الحركة', 'Dimenhydrinate - Motion Sickness', 'أطفال فوق سنتين وبالغين', 'Children over 2 years and adults', 0, '1-1.5 ملغم/كغم/جرعة', true, 1, 1.5, 50, '300', 'كل 6-8 ساعات', 'Every 6-8 hours', 'يسبب نعاساً، يُستخدم أساساً لدوار الحركة وليس القيء الناتج عن عدوى معوية', 'Causes drowsiness, used mainly for motion sickness not gastroenteritis-related vomiting', false, 'Imported from prototype; awaiting pharmacist review.');
insert into public.dosage_reference (drug_name_ar, drug_name_en, age_group_ar, age_group_en, min_weight_kg, dose_text, weight_based, per_kg_low, per_kg_high, max_single_mg, max_daily, frequency_ar, frequency_en, warnings_ar, warnings_en, requires_rx, review_note) values ('سيتيريزين (Cetirizine) - أطفال 6-11 سنة', 'Cetirizine - Children 6-11 years', 'أطفال 6-11 سنة', 'Children 6-11 years', 0, '5 ملغم/جرعة ثابتة', false, null, null, 5, '10', 'مرتين يومياً', 'Twice daily', 'قد يسبب نعاساً خفيفاً', 'May cause mild drowsiness', false, 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('head', 'صداع (Headache)', 'Headache', 'أطفال وبالغين', 'Children and adults', 'باراسيتامول أو إيبوبروفين حسب الوزن/العمر مع الراحة في غرفة مظلمة وشرب سوائل كافية', 'Paracetamol or Ibuprofen based on weight/age, rest in a dark quiet room, and adequate fluids', 'أسوأ صداع بالحياة بشكل مفاجئ، صداع مع حمى وتيبس رقبة وطفح جلدي، صداع بعد إصابة رأس، تغير بالرؤية أو الوعي', 'Sudden worst headache of life, headache with fever and neck stiffness and rash, headache after head injury, vision or consciousness changes', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('head', 'دوخة ودوار (Dizziness & Vertigo)', 'Dizziness & Vertigo', 'بالغين وأطفال فوق سنتين', 'Adults and children over 2 years', 'الراحة وتجنب الحركات المفاجئة وشرب سوائل كافية. لدوار الحركة والسفر يمكن استخدام ديمينهيدرينات حسب الوزن والجرعة', 'Rest, avoid sudden posture changes, stay hydrated. For motion sickness, Dimenhydrinate may be used based on weight/age', 'دوخة مفاجئة شديدة مصحوبة بضعف بالوجه أو الأطراف، تلعثم بالكلام، فقدان وعي، أو طنين حاد مع فقدان توازن (اشتباه سكتة دماغية طارئة)', 'Sudden severe dizziness with facial/limb weakness, slurred speech, fainting, or acute tinnitus with ataxia (suspected stroke)', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('head', 'حساسية العيون (Eye Allergy)', 'Eye Allergy', 'جميع الأعمار', 'All ages', 'كمادات باردة + قطرات عين مضادة للهيستامين + تجنب فرك العين', 'Cold compresses + antihistamine eye drops + avoid rubbing eyes', 'ألم شديد بالعين، تغير بالرؤية، إفرازات صديدية، تورم شديد بجفن واحد', 'Severe eye pain, vision changes, purulent discharge, severe swelling of one eyelid', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('head', 'حساسية الأنف (Allergic Rhinitis)', 'Allergic Rhinitis', 'أطفال فوق سنتين وبالغين', 'Children over 2 years and adults', 'مضاد هيستامين فموي (لوراتادين/سيتيريزين) + بخاخ أنف فلوتيكازون للحالات المزمنة + محلول ملحي للأنف', 'Oral antihistamine (Loratadine/Cetirizine) + Fluticasone nasal spray for chronic cases + saline nasal solution', 'نزيف أنفي متكرر شديد، صعوبة تنفس، تورم بالوجه', 'Severe recurrent nosebleeds, difficulty breathing, facial swelling', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('head', 'ألم أذن (Ear Pain)', 'Ear Pain', 'أطفال وبالغين', 'Children and adults', 'مسكن للألم (باراسيتامول أو إيبوبروفين) حسب الوزن مؤقتاً ومراجعة الطبيب لفحص طبلة الأذن', 'Weight-based pain reliever (Paracetamol or Ibuprofen) temporarily, consult doctor for otoscopic examination', 'إفرازات أو صديد أو دم من الأذن، حمى شديدة مصاحبة، تورم خلف الأذن، استمرار الألم فوق يومين', 'Discharge, pus or blood from ear, high fever, swelling behind ear, pain lasting over 2 days', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('head', 'حمى (Fever) - أطفال 3 أشهر إلى 12 سنة', 'Fever - Children 3 mo to 12 yr', 'أطفال 3 أشهر - 12 سنة', 'Children 3 months - 12 years', 'باراسيتامول أو إيبوبروفين حسب الوزن بدقة مع سوائل كافية وملابس خفيفة (راجع حاسبة الجرعات)', 'Paracetamol or Ibuprofen accurately dosed by weight, adequate fluids, and light clothing (see dosage calculator)', 'حمى فوق 3 أيام، تشنجات، طفح جلدي مع حمى، خمول شديد وصعوبة إيقاظ الطفل', 'Fever lasting over 3 days, febrile seizures, non-blanching rash with fever, extreme lethargy', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('head', 'حمى (Fever) - رضع أقل من 3 أشهر', 'Fever - Infants under 3 months', 'رضع أقل من 3 أشهر', 'Infants under 3 months', 'لا يُقترح أي دواء ذاتي إطلاقاً - التوجه الفوري لأقرب طوارئ أطفال', 'No self-medication recommended under any circumstance - go to pediatric emergency immediately', 'أي حمى عند رضيع أقل من 3 أشهر تعتبر حالة طارئة تستدعي فحوصات دم فورية', 'Any fever in an infant under 3 months is a clinical emergency requiring immediate blood tests', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('chest', 'حرقة المعدة والحموضة (Heartburn & Reflux)', 'Heartburn & Acid Reflux', 'بالغين وأطفال فوق 12 سنة', 'Adults and children over 12 years', 'مضادات الحموضة القابلة للمضغ لتسكين فوري، تجنب الاستلقاء مباشرة بعد الأكل، تجنب الأطعمة الدسمة والحارة', 'Chewable antacids for rapid relief, avoid lying down after meals, reduce fatty and spicy foods', 'ألم ضاغط أو عاصر بالصدر يمتد للذراع الأيسر أو الفك أو الظهر، مصحوب بتعرق بارد أو صعوبة تنفس (اشتباه جلطة قلبية - اتصل بالإسعاف فوراً)، صعوبة بلع، أو تقيؤ دموي', 'Crushing chest pain radiating to left arm/jaw/back with cold sweat or shortness of breath (suspected myocardial infarction - call ambulance!), dysphagia, or hematemesis', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('chest', 'ضيق التنفس (Shortness of Breath - طوارئ)', 'Shortness of Breath (Emergency)', 'جميع الأعمار', 'All ages', 'حالة طارئة تتطلب مراجعة فورية. لمرضى الربو المشخصين: أخذ بخاخ الإنقاذ الموصوف فوراً وفق الخطة الفردية والتوجه للطوارئ', 'Medical emergency requiring immediate clinical attention. Diagnosed asthma patients: take prescribed rescue inhaler immediately and head to emergency', 'حالة طارئة تستدعي الإسعاف فوراً: ازرقاق الشفاه أو الأظافر، عدم القدرة على إكمال جملة، ألم صدري حاد، أزيز شديد مفاجئ، أو حساسية شديدة وتورم في الحلق', 'Immediate ambulance emergency: cyanosis (blue lips/nails), inability to speak full sentences, severe chest pain, acute stridor/wheezing, or anaphylaxis throat swelling', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('chest', 'كحة / سعال (Cough) - فوق 6 سنوات', 'Cough - Over 6 years', 'أطفال فوق 6 سنوات وبالغين', 'Children over 6 years and adults', 'غوايفينيزين للسعال مع بلغم، أو ديكستروميثورفان للسعال الجاف، والعسل للأطفال فوق سنة', 'Guaifenesin for productive cough, Dextromethorphan for dry cough, and honey for children over 1 year', 'صعوبة تنفس، أزيز، ازرقاق، سعال مستمر فوق أسبوعين، خروج دم مع السعال', 'Difficulty breathing, wheezing, blue color, cough lasting over 2 weeks, hemoptysis (blood in sputum)', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('chest', 'كحة عند أطفال أقل من 6 سنوات', 'Cough in children under 6 years', 'أطفال أقل من 6 سنوات', 'Children under 6 years', 'لا تُستخدم أدوية السعال والبرد التجارية إطلاقاً - سوائل دافئة، عسل للأطفال فوق سنة، ومحلول ملحي للأنف', 'Never use OTC commercial cough syrups under 6 - warm fluids, honey for children over 1 year, and saline nasal spray', 'صعوبة تنفس، صوت صفير أو شخير أثناء التنفس، حمى مرتفعة، رفض الرضاعة والشرب', 'Labored breathing, stridor or audible wheezing, high fever, refusal to feed or drink', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('chest', 'سعال ونزلة برد (Cough & Cold)', 'Cough & Cold', 'أطفال فوق سنتين وبالغين', 'Children over 2 years and adults', 'محلول ملحي للأنف، شرب سوائل دافئة، مسكنات ألم خفيفة (باراسيتامول) عند الحاجة', 'Saline nasal wash, warm fluids, mild analgesics (Paracetamol) as needed', 'صعوبة تنفس، ألم حاد بالصدر، حمى مستمرة فوق 3 أيام، ازرقاق الشفاه', 'Labored breathing, sharp chest pain, fever lasting over 3 days, blue lips', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('abdomen', 'عسر الهضم والانتفاخ (Indigestion & Bloating)', 'Indigestion & Bloating', 'بالغين', 'Adults', 'مضادات الحموضة القابلة للمضغ، سيميثيكون للتخلص من الغازات، تقسيم الوجبات وتجنب المشروبات الغازية والتدخين', 'Chewable antacids, Simethicone for gas relief, smaller frequent meals, avoiding carbonated drinks and smoking', 'ألم بطني شديد ومفاجئ، يرقان (اصفرار العين والجلد)، فقدان وزن سريع غير مبرر، براز أسود داكن', 'Sudden severe abdominal pain, jaundice, unexplained rapid weight loss, melena (black tarry stool)', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('abdomen', 'مغص / ألم بطن عام (Colic/Abdominal Pain)', 'Colic / Abdominal Pain', 'أطفال وبالغين', 'Children and adults', 'لا يُقترح مسكن قوي قبل تحديد السبب تجنباً لإخفاء تشخيص جراحي - راحة ومراقبة للحالات الخفيفة فقط', 'No strong pain relievers before diagnosis to avoid masking surgical conditions - rest and hydration for mild cases only', 'ألم شديد متمركز أسفل يمين البطن (اشتباه زائدة دودية)، تصلب عضلات البطن كلوح خشبي، تقيؤ متكرر، دم بالبراز أو القيء', 'Severe localized lower right quadrant pain (suspected appendicitis), abdominal guarding/rigidity, repeated vomiting, blood in stool or vomit', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('abdomen', 'القيء والغثيان (زوع - Vomiting)', 'Vomiting & Nausea', 'جميع الأعمار', 'All ages', 'محلول إماهة فموية (ORS) برشفات صغيرة ومتكررة للوقاية من الجفاف. للحالات الشديدة: مراجعة الطبيب لتقييم الحاجة لأونداسيترون', 'Oral rehydration solution (ORS) in frequent small sips. For severe persistent cases: consult doctor for Ondansetron assessment', 'قيء دموي أو بلون أخضر/أصفر صفراوي، علامات جفاف شديد، قيء مستمر مع خمول تام، صداع شديد أو بعد ضربة على الرأس', 'Hematemesis, bilious green/yellow vomit, severe dehydration, lethargy, or severe headache following head trauma', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('abdomen', 'إسهال (Diarrhea)', 'Diarrhea', 'جميع الأعمار', 'All ages', 'محلول إماهة فموية (ORS) لتعويض السوائل والأملاح المفقودة بعد كل نوبة إسهال، والابتعاد عن العصائر السكرية', 'Oral Rehydration Solution (ORS) to replace fluids and electrolytes after each episode, avoid sugary drinks', 'دم في البراز، جفاف شديد (جفاف الفم، غؤور العينين، قلة التبول)، استمرار الإسهال أكثر من 48 ساعة عند الأطفال', 'Blood in stool (dysentery), severe dehydration (dry mucosa, sunken eyes, anuria), diarrhea persisting >48h in children', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('abdomen', 'إمساك (Constipation)', 'Constipation', 'أطفال وبالغين', 'Children and adults', 'زيادة شرب الماء والألياف الغذائية والنشاط البدني، واستخدام ملين (بيساكوديل للبالغين، أو لبوس غليسرين للرضع) عند الضرورة', 'Increase dietary fiber, water intake and physical activity; laxatives (Bisacodyl for adults, Glycerin for infants) when necessary', 'ألم بطني حاد مفاجئ، تقيؤ، انتفاخ شديد مع عدم خروج غازات (اشتباه انسداد أمعاء)، دم في البراز', 'Acute severe abdominal pain, vomiting, obstipation (no gas/stool - suspected obstruction), hematochezia', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('abdomen', 'المغص المعوي عند الرضع (Infantile Colic)', 'Infantile Colic', 'رضع أقل من 4-5 أشهر', 'Infants under 4-5 months', 'طمأنة الأهل، تدليك بطن الرضيع بلطف، تجربة نقاط سيميثيكون بعد الرضاعة، وتعديل وضعية الإرضاع والتجشؤ', 'Reassure parents, gentle tummy massage, trial of Simethicone drops after feeds, upright feeding position and burping', 'بكاء مستمر مع حمى، قيء صفراوي، دم بالبراز، توقف زيادة الوزن، أو خمول غير طبيعي', 'Inconsolable crying with fever, bilious vomiting, bloody stool, failure to thrive, abnormal lethargy', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('skin', 'طفح جلدي (Skin Rash)', 'Skin Rash', 'جميع الأعمار', 'All ages', 'لا يُقترح دواء ذاتي بدون تشخيص دقيق لسبب الطفح - يمكن استخدام كمادات باردة أو مرطبات خالية من العطور', 'No self-medication without professional etiology identification - cold compresses or fragrance-free emollients may soothe', 'طفح مصحوب بحمى، طفح لا يختفي لونه عند الضغط عليه بزجاج شفاف (اشتباه عدوى سحائية)، صعوبة تنفس أو تورم بالوجه', 'Rash with fever, non-blanching petechial/purpuric rash (suspected meningococcemia), breathing difficulty, facial angioedema', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('skin', 'حساسية الجلد (Skin Allergy & Hives)', 'Skin Allergy & Hives', 'جميع الأعمار', 'All ages', 'هيدروكورتيزون كريم 1% موضعياً للحكة المحدودة + مضاد هيستامين فموي (سيتيريزين أو لوراتادين)', 'Topical Hydrocortisone 1% cream for localized itching + oral antihistamine (Cetirizine or Loratadine)', 'تورم الوجه أو الشفاه أو اللسان، صعوبة بالتنفس أو البلع، بحة بالصوت، دوخة وهبوط ضغط (صدمة تأقية طارئة - اطلب الإسعاف فوراً)', 'Angioedema of face/lips/tongue, difficulty breathing or swallowing, hoarseness, hypotension (Anaphylaxis - call emergency immediately!)', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('limbs', 'ألم وخشونة المفاصل (Joint Pain & Arthritis)', 'Joint Pain & Stiffness (Arthritis / Arthralgia)', 'بالغين وكبار السن', 'Adults & elderly', 'ديكلوفيناك جل موضعي 1% أو باراسيتامول لتخفيف الألم مع كمادات دافئة للخشونة الصباحية وتجنب إجهاد المفصل', 'Topical Diclofenac 1% gel or oral Paracetamol for pain relief, warm compresses for morning stiffness, avoid joint strain', 'احمرار وتورم ساخن وحاد بمفصل واحد مع حمى وقشعريرة (اشتباه التهاب مفصل إنتاني صديدي طارئ)، عدم القدرة على تحريك المفصل تماماً، أو تشوه مفاجئ', 'Acute hot red swollen joint with fever and chills (suspected septic arthritis emergency), total joint immobility, or sudden visible deformity', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('limbs', 'الشد والتمزق العضلي والإجهاد (Muscle Strain & Cramps)', 'Muscle Strain, Spasms & Cramps', 'أطفال فوق 12 سنة وبالغين', 'Over 12 years & adults', 'بروتوكول RICE في أول 48 ساعة (راحة، كمادات ثلج، رباط ضاغط، رفع الطرف) + لصقات تسكين أو جل موضعي + إيبوبروفين لتخفيف الالتهاب', 'RICE protocol in first 48 hours (Rest, Ice, Compression, Elevation) + menthol pain relief patches or gel + Ibuprofen for inflammation', 'ألم حاد متزايد مع تورم قاسي وبرودة في القدم/الساق أو ازرقاق وخدر، تورم وألم شديد في ربلة الساق (بطة الساق) بعد سفر أو خمول (اشتباه جلطة وريدية DVT)', 'Compartment syndrome signs (severe unrelenting pain, pallor, pulselessness, paresthesia), unilateral calf swelling/tenderness (suspected DVT)', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('limbs', 'آلام أسفل الظهر والفقرات (Lower Back Pain & Lumbago)', 'Lower Back Pain & Spine Strain', 'بالغين', 'Adults', 'المحافظة على حركة خفيفة ومشي وتجنب الراحة التامة بالسرير + لصقات تسكين دافئة أو جل موضعي مسكن + باراسيتامول أو إيبوبروفين لفترة قصيرة', 'Maintain gentle activity and light walking, avoid prolonged bed rest + warm pain patches or topical gel + short course of Paracetamol or Ibuprofen', 'فقدان التحكم في التبول أو التبرز، خدر وتنميل بمنطقة المقعدة والأعضاء التناسلية (متلازمة ذيل الفرس الطارئة Cauda Equina)، ضعف مفاجئ بسقوط القدم، ألم متصاعد مع حمى', 'Loss of bowel/bladder control, saddle anesthesia in groin/perineum (Cauda Equina Syndrome emergency), sudden foot drop, or back pain with fever', 'Imported from prototype; awaiting pharmacist review.');
insert into public.symptom_reference (body_region, name_ar, name_en, age_group_ar, age_group_en, suggestion_ar, suggestion_en, red_flags_ar, red_flags_en, review_note) values ('limbs', 'التواء الأربطة والكدمات العظمية (Sprains & Bone Bruises)', 'Ligament Sprains & Bone Contusions', 'جميع الأعمار', 'All ages', 'تثبيت المفصل برباط مطاطي داعم، كمادات ثلج 15-20 دقيقة، مسكن باراسيتامول أو جل موضعي مسكن، ورفع العضو المصاب', 'Supportive elastic bandage immobilization, ice compresses 15-20 min, Paracetamol or topical gel, elevate the limb', 'عدم القدرة على الوقوف أو تحميل الوزن على الطرف نهائياً لأكثر من 4 خطوات (معايير أوتاوا للاشتباه بالكسر العظمي)، ألم حاد عند لمس العظم مباشرة، أو صوت فرقعة حاد وقت الإصابة', 'Inability to bear weight immediately and take 4 steps (Ottawa fracture criteria), exquisite bony tenderness, severe deformity, or audible snap/pop at injury', 'Imported from prototype; awaiting pharmacist review.');
